-- ===========================================================================
-- 0043_kampus_prodi_relevan.sql
--
-- "Kampus dengan program studi relevan" di layar detail profesi.
--
-- Sumber: direktori hasil akreditasi program studi BAN-PT
-- (https://www.banpt.or.id/direktori/prodi/pencarian_prodi.php), diunduh
-- 16 Oktober 2026: 36.790 program studi, termasuk hasil akreditasi LAM yang
-- tercatat di direktori itu. Hanya program S1, D4, dan D3 yang akreditasinya
-- masih berlaku dan bukan "Tidak Terakreditasi" yang dipakai. Nama kampus
-- dirapikan (kode di depan dibuang, huruf kapital semua diubah) supaya satu
-- kampus tidak muncul dua kali.
--
-- Dua lapis, dipakai berurutan:
--   1. campus_paths       kampus per JALUR PENDIDIKAN profesi (tabel 0034:
--                         "Sarjana (S1) Farmasi", "Diploma (D3) Keperawatan").
--                         Bidang studi di sana sudah dikurasi per profesi,
--                         jadi lebih tepat. 152 jalur punya kampus.
--   2. study_program_campuses  cadangan untuk profesi yang jalurnya tidak punya
--                         padanan: kampus per program studi Navika, lewat
--                         education_career (relevance >= 80 kalau ada).
-- Untuk tiap kunci disimpan paling banyak 15 (jalur) atau 25 (cadangan) kampus:
-- akreditasi tertinggi dulu (Unggul/A), lalu jenjang jalur itu, lalu PTN/PTAN/
-- PTKL, lalu nama. Saat ditampilkan, kampus dengan akreditasi dan jenjang sama
-- diurutkan menurut jumlah program studi Unggul/A yang dimilikinya di BAN-PT
-- (n_unggul), ukuran netral dan berbasis data untuk mutu institusi.
--
-- Ini daftar kampus yang MENYELENGGARAKAN program studi, bukan data alumni
-- atau tempat kerja lulusan.
--
-- Jalankan setelah 0042. Aman diulang (isi tabel diganti seluruhnya).
-- ===========================================================================

begin;

create table if not exists public.campus_paths (
  path_title    text     not null,   -- = career_education_paths.title_id
  path_level    text     not null,   -- = career_education_paths.level_code
  pt_name       text     not null,
  prodi_banpt   text     not null,
  jenjang       text     not null,
  akreditasi    text     not null,
  tingkat       smallint not null,   -- 1 Unggul/A, 2 Baik Sekali/B, 3 lainnya
  negeri        boolean  not null,
  n_unggul      integer  not null,   -- jumlah program studi Unggul/A milik kampus ini di BAN-PT
  primary key (path_title, path_level, pt_name)
);
create table if not exists public.study_program_campuses (
  study_program_id integer  not null references public.study_programs(id) on delete cascade,
  pt_name          text     not null,
  prodi_banpt      text     not null,
  jenjang          text     not null,
  akreditasi       text     not null,
  tingkat          smallint not null,
  negeri           boolean  not null,
  n_unggul         integer  not null,
  primary key (study_program_id, pt_name)
);
comment on table public.campus_paths is
  'Kampus per jalur pendidikan profesi, dari direktori akreditasi BAN-PT (diunduh 16 Oktober 2026). Lihat 0043.';
comment on table public.study_program_campuses is
  'Kampus per program studi Navika (cadangan), dari direktori akreditasi BAN-PT (diunduh 16 Oktober 2026). Lihat 0043.';

alter table public.campus_paths enable row level security;
alter table public.study_program_campuses enable row level security;
do $$
begin
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='campus_paths' and policyname='campus_paths_read_all') then
    create policy campus_paths_read_all on public.campus_paths for select to anon, authenticated using (true);
  end if;
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='study_program_campuses' and policyname='study_program_campuses_read_all') then
    create policy study_program_campuses_read_all on public.study_program_campuses for select to anon, authenticated using (true);
  end if;
end $$;

delete from public.campus_paths;
on conflict do nothing;

delete from public.study_program_campuses;
on conflict do nothing;

-- ---------------------------------------------------------------------------
-- Kampus untuk satu profesi: lapis jalur dulu; cadangan hanya kalau kosong.
-- Satu kampus tampil sekali, dengan akreditasi dan jenjang terbaiknya.
-- ---------------------------------------------------------------------------
drop function if exists public.kampus_relevan(integer, integer);
create function public.kampus_relevan(p_career_id integer, p_limit integer default 6)
returns table (
  pt_name     text,
  prodi       text,
  jenjang     text,
  akreditasi  text,
  negeri      boolean,
  n_kampus    integer
)
language sql stable
set search_path = public
as $$
  with lewat_jalur as (
    select k.pt_name, k.prodi_banpt as prodi, k.jenjang, k.akreditasi, k.negeri, k.tingkat, k.n_unggul,
           case p.level_code when 'S1' then 0 when 'D4' then 1 else 2 end as urut_jenjang
    from career_education_paths p
    join campus_paths k on k.path_title = p.title_id and k.path_level = p.level_code
    where p.career_id = p_career_id
  ),
  prodi_relevan as (
    select e.source_id, e.relevance
    from education_career e
    where e.source_kind = 'PRODI' and e.career_id = p_career_id
  ),
  lewat_prodi as (
    select k.pt_name, sp.name_id as prodi, k.jenjang, k.akreditasi, k.negeri, k.tingkat, k.n_unggul,
           case k.jenjang when 'S1' then 0 when 'D4' then 1 else 2 end as urut_jenjang
    from prodi_relevan r
    join study_programs sp on sp.id = r.source_id
    join study_program_campuses k on k.study_program_id = r.source_id
    where r.relevance >= case when exists (select 1 from prodi_relevan where relevance >= 80) then 80 else 0 end
      and not exists (select 1 from lewat_jalur)
  ),
  semua as (select * from lewat_jalur union all select * from lewat_prodi),
  per_kampus as (
    select distinct on (pt_name) *
    from semua
    order by pt_name, tingkat, urut_jenjang
  )
  select pt_name, prodi, jenjang, akreditasi, negeri, (count(*) over ())::integer
  from per_kampus
  order by tingkat, urut_jenjang, n_unggul desc, pt_name
  limit greatest(p_limit, 1);
$$;

comment on function public.kampus_relevan(integer, integer) is
  'Kampus yang menyelenggarakan program studi untuk sebuah profesi (sumber: BAN-PT). n_kampus = jumlah seluruh kampus yang cocok.';

grant execute on function public.kampus_relevan(integer, integer) to anon, authenticated;

commit;
